"""Host tests for the SERVER reference protocol; not ESP32 hardware tests."""
import copy
import hashlib
import hmac
from pathlib import Path
import struct
import subprocess
import sys
import tempfile
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "tools"))
from ota_protocol import command_text, manifest_text, release, sign, trusted_url


class ProtocolTests(unittest.TestCase):
    def setUp(self):
        # Fixed TEST-ONLY key. Production keys are generated by provision.py.
        self.cfg = dict(device="ESP32_001", trust_base="https://firmware.example.test/fw/",
                        key_hex="12" * 32)
        self.image = bytearray(1024)
        self.image[0] = 0xE9
        struct.pack_into("<I", self.image, 32, 0xABCD5432)
        self.image[48:53] = b"1.1.0"
        self.image[80:91] = b"smartcharge"
        self.command, self.manifest = release(self.cfg, self.image, "ota-001", 1,
            self.cfg["trust_base"] + "manifest/ota-001", self.cfg["trust_base"] + "1.1.0.bin")

    def test_command_signature_round_trip(self):
        self.assertTrue(hmac.compare_digest(self.command["signature"],
            sign(command_text(self.command), self.cfg["key_hex"])))

    def test_wrong_device_and_replayed_sequence_are_bound(self):
        for field, value in (("device", "ESP32_999"), ("seq", "2"),
                             ("version", "1.2.0"), ("request_id", "other")):
            altered = dict(self.command, **{field: value})
            self.assertNotEqual(self.command["signature"], sign(command_text(altered), self.cfg["key_hex"]))

    def test_manifest_binds_hash_size_chip_and_version(self):
        self.assertEqual(self.manifest["sha256"], hashlib.sha256(self.image).hexdigest())
        for field, value in (("sha256", "0" * 64), ("size", 1025), ("version", "9.0.0")):
            altered = dict(self.manifest, **{field: value})
            self.assertNotEqual(self.manifest["signature"], sign(manifest_text(altered), self.cfg["key_hex"]))

    def test_cross_protocol_signature_rejected(self):
        self.assertNotEqual(self.command["signature"], self.manifest["signature"])

    def test_untrusted_urls(self):
        base = self.cfg["trust_base"]
        for url in ("http://firmware.example.test/fw/a", "https://evil.test/fw/a",
                    "https://firmware.example.test.evil.test/fw/a", base + "../a",
                    base + "%2e%2e/a", base + "a?token=secret", base + "a\n"):
            self.assertFalse(trusted_url(url, base), url)

    def test_wrong_chip_and_non_smartcharge(self):
        changed = copy.copy(self.image)
        struct.pack_into("<H", changed, 12, 9)
        with self.assertRaises(ValueError):
            release(self.cfg, changed, "ota-002", 2, self.command["manifest_url"], self.manifest["url"])
        changed = copy.copy(self.image)
        changed[80:91] = b"recovery\0\0\0"
        with self.assertRaises(ValueError):
            release(self.cfg, changed, "ota-002", 2, self.command["manifest_url"], self.manifest["url"])

    def test_size_guard_rejects_equal_and_overflow(self):
        guard = Path(__file__).resolve().parents[1] / "tools/check_artifact.py"
        with tempfile.TemporaryDirectory() as directory:
            binary = Path(directory) / "recovery.bin"
            for size, expected in ((1023, 0), (1024, 1), (1025, 1)):
                binary.write_bytes(bytes(size))
                result = subprocess.run([sys.executable, str(guard), str(binary), "1024"], capture_output=True)
                self.assertEqual(result.returncode, expected)


if __name__ == "__main__":
    unittest.main()
